from pycompss.api.task import task
from pycompss.api.api import compss_wait_on

@task(returns=1)
def get_neighbors_task(node_row):
    return [i for i, connected in enumerate(node_row) if connected == 1]      

def main(A, source, dest):
    if source == dest:
        return 0

    visited = {source}
    frontier = [source]
    distance = 0

    while frontier:
        distance += 1

        neighbor_tasks = [get_neighbors_task(A[node]) for node in frontier]

        neighbor_lists = compss_wait_on(neighbor_tasks)

        next_frontier = set()
        for neighbors in neighbor_lists:
            for neighbor in neighbors:
                if neighbor == dest:
                    return distance
                if neighbor not in visited:
                    visited.add(neighbor)
                    next_frontier.add(neighbor)

        frontier = list(next_frontier)

    return -1
